        row_len = len(grid[r])
        for c in range(min(W_actual, row_len)):
            if grid[r][c] != 0 and not visited[r][c]:
                queue = [(r,c)]
                component = []
                visited[r][c] = True
                idx = 0
                while idx < len(queue):
                    cr, cc = queue[idx]
                    idx += 1
                    component.append((cr, cc))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
